package ru.murad.yourmarket.service.impl;
import lombok.RequiredArgsConstructor;import lombok.extern.slf4j.Slf4j;import org.springframework.stereotype.Service;import ru.murad.yourmarket.service.*;import ru.murad.yourmarket.telegram.TelegramGateway;import java.util.UUID;
@Slf4j @Service @RequiredArgsConstructor public class AdvertisementExpirationServiceImpl implements AdvertisementExpirationService {private final AdvertisementLifecycleTransactionService lifecycle;private final ChannelMessageDeletionService deletion;private final TelegramGateway telegram;
@Override public boolean expire(UUID id){var claim=lifecycle.claimExpiration(id);if(claim==null)return false;if(!deletion.deleteAll(id)){lifecycle.releaseExpiration(id,claim.operationId());return false;}var ad=lifecycle.finishExpiration(id,claim.operationId());if(ad==null)return false;try{telegram.sendText(ad.getChatId(),"Срок публикации объявления истёк");}catch(RuntimeException ex){log.warn("Не отправлено уведомление об истечении advertisementId={}",id);}return true;}}
